   771  // Merge a list of meshes
   772  void SceneCombiner::MergeMeshes(aiMesh **_out, unsigned int /*flags*/,
   773          MeshArray::const_iterator begin,
   774          MeshArray::const_iterator end) {
   775      if (nullptr == _out) {
   776          return;
   777      }
   778
   779      if (begin == end) {
   780          *_out = nullptr; // no meshes ...
   781          return;
   782      }
   783
   784      // Allocate the output mesh
   785      aiMesh *out = *_out = new aiMesh();
   786      out->mMaterialIndex = (*begin)->mMaterialIndex;
   787
   788      std::string name;
   789      // Find out how much output storage we'll need
   790      for (MeshArray::const_iterator it = begin; it != end; ++it) {
   791          const char *meshName((*it)->mName.C_Str());
   792          name += std::string(meshName);
   793          if (it != end - 1) {
   794              name += ".";
   795          }
   796          out->mNumVertices += (*it)->mNumVertices;
   797          out->mNumFaces += (*it)->mNumFaces;
   798          out->mNumBones += (*it)->mNumBones;
   799
   800          // combine primitive type flags
   801          out->mPrimitiveTypes |= (*it)->mPrimitiveTypes;
   802      }
   803      out->mName.Set(name.c_str());
   804
   805      if (out->mNumVertices) {
   806          aiVector3D *pv2;
   807
   808          // copy vertex positions
   809          if ((**begin).HasPositions()) {
   810
   811              pv2 = out->mVertices = new aiVector3D[out->mNumVertices];
   812              for (MeshArray::const_iterator it = begin; it != end; ++it) {
   813                  if ((*it)->mVertices) {
   814                      ::memcpy(pv2, (*it)->mVertices, (*it)->mNumVertices * sizeof(aiVector3D));
   815                  } else
   816                      ASSIMP_LOG_WARN("JoinMeshes: Positions expected but input mesh contains no positions");
   817                  pv2 += (*it)->mNumVertices;
   818              }
   819          }
   820          // copy normals
   821          if ((**begin).HasNormals()) {
   822
   823              pv2 = out->mNormals = new aiVector3D[out->mNumVertices];
   824              for (MeshArray::const_iterator it = begin; it != end; ++it) {
   825                  if ((*it)->mNormals) {
   826                      ::memcpy(pv2, (*it)->mNormals, (*it)->mNumVertices * sizeof(aiVector3D));
   827                  } else {
   828                      ASSIMP_LOG_WARN("JoinMeshes: Normals expected but input mesh contains no normals");
   829                  }
   830                  pv2 += (*it)->mNumVertices;
   831              }
   832          }
   833          // copy tangents and bi-tangents
   834          if ((**begin).HasTangentsAndBitangents()) {
   835
   836              pv2 = out->mTangents = new aiVector3D[out->mNumVertices];
   837              aiVector3D *pv2b = out->mBitangents = new aiVector3D[out->mNumVertices];
   838
   839              for (MeshArray::const_iterator it = begin; it != end; ++it) {
   840                  if ((*it)->mTangents) {
   841                      ::memcpy(pv2, (*it)->mTangents, (*it)->mNumVertices * sizeof(aiVector3D));
   842                      ::memcpy(pv2b, (*it)->mBitangents, (*it)->mNumVertices * sizeof(aiVector3D));
   843                  } else {
   844                      ASSIMP_LOG_WARN("JoinMeshes: Tangents expected but input mesh contains no tangents");
   845                  }
   846                  pv2 += (*it)->mNumVertices;
   847                  pv2b += (*it)->mNumVertices;
   848              }
   849          }
   850          // copy texture coordinates
   851          unsigned int n = 0;
   852          while ((**begin).HasTextureCoords(n)) {
   853              out->mNumUVComponents[n] = (*begin)->mNumUVComponents[n];
   854
   855              pv2 = out->mTextureCoords[n] = new aiVector3D[out->mNumVertices];
   856              for (MeshArray::const_iterator it = begin; it != end; ++it) {
   857                  if ((*it)->mTextureCoords[n]) {
   858                      ::memcpy(pv2, (*it)->mTextureCoords[n], (*it)->mNumVertices * sizeof(aiVector3D));
   859                  } else {
   860                      ASSIMP_LOG_WARN("JoinMeshes: UVs expected but input mesh contains no UVs");
   861                  }
   862                  pv2 += (*it)->mNumVertices;
   863              }
   864              ++n;
   865          }
   866          // copy vertex colors
   867          n = 0;
   868          while ((**begin).HasVertexColors(n)) {
   869              aiColor4D *pVec2 = out->mColors[n] = new aiColor4D[out->mNumVertices];
   870              for (MeshArray::const_iterator it = begin; it != end; ++it) {
   871                  if ((*it)->mColors[n]) {
   872                      ::memcpy(pVec2, (*it)->mColors[n], (*it)->mNumVertices * sizeof(aiColor4D));
   873                  } else {
   874                      ASSIMP_LOG_WARN("JoinMeshes: VCs expected but input mesh contains no VCs");
   875                  }
   876                  pVec2 += (*it)->mNumVertices;
   877              }
   878              ++n;
   879          }
   880      }
   881
   882      if (out->mNumFaces) // just for safety
   883      {
   884          // copy faces
   885          out->mFaces = new aiFace[out->mNumFaces];
   886          aiFace *pf2 = out->mFaces;
   887
   888          unsigned int ofs = 0;
   889          for (MeshArray::const_iterator it = begin; it != end; ++it) {
   890              for (unsigned int m = 0; m < (*it)->mNumFaces; ++m, ++pf2) {
   891                  aiFace &face = (*it)->mFaces[m];
   892                  pf2->mNumIndices = face.mNumIndices;
   893                  pf2->mIndices = face.mIndices;
   894
   895                  if (ofs) {
   896                      // add the offset to the vertex
   897                      for (unsigned int q = 0; q < face.mNumIndices; ++q) {
   898                          face.mIndices[q] += ofs;
   899                      }
   900                  }
   901                  face.mIndices = nullptr;
   902              }
   903              ofs += (*it)->mNumVertices;
   904          }
   905      }
   906
   907      // bones - as this is quite lengthy, I moved the code to a separate function
   908      if (out->mNumBones)
   909          MergeBones(out, begin, end);
   910
   911      // delete all source meshes
   912      for (MeshArray::const_iterator it = begin; it != end; ++it)
   913          delete *it;
   914  }
